css:
.iso-sim-container {
    padding: 28px 24px;
    background: #f4f5f7;
    min-height: 100vh;
    font-family: -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
    color: #1a2744;
}
.iso-sim-header {
    background: linear-gradient(135deg, #1a2744 0%, #2c3e6b 100%);
    color: #ffffff;
    border-radius: 4px;
    padding: 32px 36px 28px;
    margin-bottom: 24px;
    position: relative;
    overflow: hidden;
}
.iso-sim-header::after {
    content: '';
    position: absolute;
    top: 0; right: 0;
    width: 200px; height: 100%;
    background: linear-gradient(135deg, transparent 40%, rgba(255,255,255,0.04) 100%);
}
.iso-sim-header-badge {
    display: inline-block;
    background: rgba(255,255,255,0.15);
    border: 1px solid rgba(255,255,255,0.25);
    border-radius: 3px;
    padding: 3px 12px;
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    margin-bottom: 12px;
}
.iso-sim-header h1 {
    font-size: 1.5rem;
    font-weight: 700;
    margin: 0 0 6px;
    letter-spacing: -0.01em;
}
.iso-sim-subtitle {
    margin: 0;
    font-size: 0.9rem;
    color: rgba(255,255,255,0.7);
    font-weight: 400;
}
.iso-sim-period-counter {
    text-align: center;
    font-size: 0.85rem;
    color: #5a6a80;
    margin-bottom: 20px;
    font-weight: 600;
    letter-spacing: 0.05em;
    text-transform: uppercase;
}
.iso-sim-period-counter span {
    margin: 0 3px;
}
.iso-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 20px;
}
.iso-sim-kpi-card {
    background: #ffffff;
    border-radius: 4px;
    padding: 20px 16px;
    border: 1px solid #e1e4e8;
    border-top: 3px solid #1a2744;
    transition: box-shadow 0.2s ease;
}
.iso-sim-kpi-card:hover {
    box-shadow: 0 4px 12px rgba(26,39,68,0.08);
}
.iso-sim-kpi-budget { border-top-color: #1a2744; }
.iso-sim-kpi-qms { border-top-color: #0969da; }
.iso-sim-kpi-compliance { border-top-color: #1a7f37; }
.iso-sim-kpi-docs { border-top-color: #8250df; }
.iso-sim-kpi-label {
    font-size: 0.7rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #656d76;
    margin-bottom: 8px;
}
.iso-sim-kpi-value {
    font-size: 1.65rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1.1;
}
.iso-sim-kpi-qms .iso-sim-kpi-value { color: #0969da; }
.iso-sim-kpi-compliance .iso-sim-kpi-value { color: #1a7f37; }
.iso-sim-kpi-docs .iso-sim-kpi-value { color: #8250df; }
.iso-sim-risk-bar-container {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #ffffff;
    border: 1px solid #e1e4e8;
    border-radius: 4px;
    padding: 14px 20px;
    margin-bottom: 20px;
}
.iso-sim-risk-label {
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #656d76;
    white-space: nowrap;
}
.iso-sim-risk-track {
    flex: 1;
    height: 10px;
    background: #e8ecf0;
    border-radius: 5px;
    overflow: hidden;
}
.iso-sim-risk-fill {
    height: 100%;
    background: linear-gradient(90deg, #cf222e, #da6d25);
    border-radius: 5px;
    transition: width 0.5s ease;
}
.iso-sim-risk-value {
    font-size: 0.85rem;
    font-weight: 700;
    color: #cf222e;
    min-width: 36px;
    text-align: right;
}
.iso-sim-briefing {
    background: #ffffff;
    border: 1px solid #e1e4e8;
    border-left: 4px solid #0969da;
    border-radius: 4px;
    padding: 22px 24px;
    margin-bottom: 20px;
}
.iso-sim-briefing-title {
    font-size: 0.95rem;
    font-weight: 700;
    color: #1a2744;
    margin-bottom: 8px;
}
.iso-sim-briefing-text {
    font-size: 0.85rem;
    color: #444d56;
    line-height: 1.65;
}
.iso-sim-controls {
    background: #ffffff;
    border: 1px solid #e1e4e8;
    border-radius: 4px;
    padding: 24px;
    margin-bottom: 20px;
}
.iso-sim-controls h3 {
    font-size: 0.85rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #1a2744;
    margin: 0 0 18px;
    padding-bottom: 10px;
    border-bottom: 1px solid #e8ecf0;
}
.iso-sim-controls-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 20px;
    margin-bottom: 20px;
}
.iso-sim-control-group {
    display: flex;
    flex-direction: column;
}
.iso-sim-control-group label {
    font-size: 0.78rem;
    font-weight: 600;
    color: #444d56;
    margin-bottom: 6px;
}
.iso-sim-control-group input[type="number"],
.iso-sim-control-group select {
    background: #f6f8fa;
    border: 1px solid #d0d7de;
    border-radius: 3px;
    padding: 9px 12px;
    font-size: 0.9rem;
    color: #1a2744;
    font-weight: 600;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.iso-sim-control-group input:focus,
.iso-sim-control-group select:focus {
    outline: none;
    border-color: #0969da;
    box-shadow: 0 0 0 3px rgba(9,105,218,0.12);
}
.iso-sim-hint {
    font-size: 0.7rem;
    color: #8b949e;
    margin-top: 4px;
}
.iso-sim-btn-row {
    display: flex;
    gap: 10px;
}
.iso-sim-btn-primary {
    background: #1a2744;
    color: #ffffff;
    border: none;
    border-radius: 3px;
    padding: 10px 28px;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s ease;
}
.iso-sim-btn-primary:hover {
    background: #2c3e6b;
    color: #ffffff;
}
.iso-sim-btn-outline {
    background: transparent;
    color: #656d76;
    border: 1px solid #d0d7de;
    border-radius: 3px;
    padding: 10px 20px;
    font-size: 0.8rem;
    font-weight: 500;
    cursor: pointer;
    transition: border-color 0.2s ease;
}
.iso-sim-btn-outline:hover {
    border-color: #1a2744;
    color: #1a2744;
}
.iso-sim-chart-area {
    background: #ffffff;
    border: 1px solid #e1e4e8;
    border-radius: 4px;
    padding: 20px;
    margin-bottom: 20px;
    height: 280px;
}
.iso-sim-history {
    background: #ffffff;
    border: 1px solid #e1e4e8;
    border-radius: 4px;
    overflow: hidden;
}
.iso-sim-container .table {
    margin: 0;
    font-size: 0.82rem;
}
.iso-sim-container .table thead th {
    background: #f6f8fa;
    border-bottom: 2px solid #d0d7de;
    color: #444d56;
    font-weight: 600;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    padding: 10px 12px;
}
.iso-sim-container .table td {
    padding: 9px 12px;
    border-color: #e8ecf0;
    color: #1a2744;
}
@media (max-width: 768px) {
    .iso-sim-container { padding: 16px 12px; }
    .iso-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .iso-sim-controls-grid { grid-template-columns: 1fr; }
    .iso-sim-header { padding: 24px 20px 20px; }
    .iso-sim-header h1 { font-size: 1.2rem; }
    .iso-sim-kpi-value { font-size: 1.3rem; }
    .iso-sim-btn-row { flex-direction: column; }
}

