                (v) => 'COP ' + Math.round(v).toLocaleString() + 'M');
            uiManager.bind('qmsDisplay', 'domainState.qmsReadiness',
                (v) => Math.round(v) + '%');
            uiManager.bind('complianceDisplay', 'domainState.employeeCompliance',
                (v) => Math.round(v) + '%');
            uiManager.bind('docsDisplay', 'domainState.documentationLevel',
                (v) => Math.round(v) + '%');
            uiManager.bind('riskDisplay', 'domainState.riskLevel',
                (v) => Math.round(v) + '%');


            if (!this._wired) {
                var _self = this;
                var _refresh = function() { try { _self._updateBriefing(window.mySimulation.state); } catch (e) {} };
                var _sim = window.mySimulation;
                if (_sim && _sim.eventBus && typeof _sim.eventBus.on === 'function') {
                    _sim.eventBus.on('period:submitted', _refresh);
                    _sim.eventBus.on('period:undone', _refresh);
                }
                document.addEventListener('express:langchanged', _refresh);
                this._wired = true;
            }
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && typeof sim.t === 'function') ? sim.t(key) : key;
        }

