        getChartData(state) {
            var self = this;
            var labels = state.domainState.qmsHistory.map(function(_, i) { return self._t('phase_label') + ' ' + (i + 1); });
            return {
                readinessChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.qmsHistory, label: this._t('chart_qms') },
                        { data: state.domainState.complianceHistory, label: this._t('chart_compliance') },
                        { data: state.domainState.docHistory, label: this._t('chart_docs') }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var ds = window.mySimulation.state.domainState;
            var totalSpent = 250 - ds.budget;
            var auditScore = ds.auditScore || 0;
            var certified = ds.certified || false;

            var performance = this._t('perf_needs_improvement');
            if (certified && ds.budget > 50) performance = this._t('perf_excellent');
            else if (certified && ds.budget > 0) performance = this._t('perf_good');
            else if (certified) performance = this._t('perf_satisfactory');

            var insights = [];
            if (certified) {
                insights.push(this._t('ins_certified'));
                if (ds.budget > 80) insights.push(this._t('ins_budget_outstanding'));
                else if (ds.budget > 30) insights.push(this._t('ins_budget_good'));
                else insights.push(this._t('ins_budget_tight'));
            } else {
                insights.push(this._t('ins_not_certified'));
                if (ds.qmsReadiness < 70) insights.push(this._t('ins_low_qms'));
                if (ds.employeeCompliance < 60) insights.push(this._t('ins_low_compliance'));
                if (ds.documentationLevel < 60) insights.push(this._t('ins_low_docs'));
            }

            return {
                totalSpent: totalSpent,
                budgetRemaining: ds.budget,
                auditScore: auditScore,
                certified: this._t(certified ? 'certified_yes' : 'certified_no'),
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (state.currentPeriod === 1 && results.qmsGain < 20) {
                return window.mySimulation.t('hint_low_invest');
            }
            if (results.riskLevel > 60 && state.currentPeriod >= 2) {
                return window.mySimulation.t('hint_high_risk');
            }
            if (state.domainState.budget < 60 && state.currentPeriod < 4) {
                return window.mySimulation.t('hint_low_budget');
            }
            if (results.compliance < 40 && state.currentPeriod >= 2) {
                return window.mySimulation.t('hint_low_compliance');
            }
            if (state.currentPeriod === 4 && results.certified) {
                return window.mySimulation.t('hint_certified');
            }
            if (state.currentPeriod === 4 && !results.certified) {
                return window.mySimulation.t('hint_failed');
            }
            return null;
        }

