        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) titleEl.innerHTML = this._t('round_' + (idx + 1) + '_title');

            var textEl = document.getElementById('briefingText');
            if (textEl) textEl.innerHTML = this._t('round_' + (idx + 1) + '_desc');

            var riskBar = document.getElementById('riskBar');
            if (riskBar && window.mySimulation && window.mySimulation.state) {
                riskBar.style.width = (window.mySimulation.state.domainState.riskLevel || 80) + '%';
            }
        }
